<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Designer Deck Template v1</title>
    <style>
      @import url("https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800&display=swap");

      :root {
        --ink: #111111;
        --muted: #6f7785;
        --line: rgba(0, 0, 0, 0.9);
        --accent: #1E40AF; /* Deep muted blue */
        --accent-light: #EFF6FF;
        --field-bg: #F4F5F7;
        --card-bg: #FFFFFF;
      }

      * {
        box-sizing: border-box;
      }

      html,
      body {
        margin: 0;
        width: 1920px;
        height: 1080px;
        overflow: hidden;
        background: #ffffff;
        font-family: "Montserrat", sans-serif;
        color: var(--ink);
      }

      .slide {
        position: relative;
        width: 100%;
        height: 100%;
        background: #ffffff;
      }

      .header {
        position: absolute;
        left: 92px;
        top: 62px;
        margin: 0;
        font-size: 64px;
        line-height: 1.04;
        font-weight: 700;
        letter-spacing: -0.05em;
        width: 1736px;
      }

      .subheader {
        position: absolute;
        left: 92px;
        top: 154px;
        margin: 0;
        font-size: 27px;
        line-height: 1.28;
        font-weight: 400;
        letter-spacing: -0.02em;
        color: var(--muted);
      }

      .footer-line {
        position: absolute;
        left: 112px;
        top: 992px;
        width: 1536px;
        height: 1px;
        background: var(--line);
      }

      .footer-logo {
        position: absolute;
        left: 1692px;
        top: 962px;
        width: 114px;
        height: 59px;
        object-fit: contain;
      }

      /* Master Card Layout */
      .master-card {
        position: absolute;
        left: 92px;
        top: 250px;
        width: 1736px;
        height: 660px;
        background: var(--field-bg);
        border-radius: 32px;
        padding: 40px;
        display: flex;
        flex-direction: column;
        gap: 32px;
      }

      .top-section {
        display: flex;
        gap: 40px;
        flex: 1;
      }

      /* Left Ask Block */
      .ask-block {
        background: var(--card-bg);
        border-radius: 24px;
        padding: 56px 48px;
        box-shadow: 0 4px 24px rgba(0, 0, 0, 0.03), 0 1px 4px rgba(0, 0, 0, 0.02);
        flex: 0 0 480px;
        display: flex;
        flex-direction: column;
        justify-content: center;
      }

      .ask-amount {
        font-size: 104px;
        font-weight: 700;
        letter-spacing: -0.04em;
        color: var(--accent);
        line-height: 1;
        margin-bottom: 16px;
      }

      .ask-instrument {
        font-size: 26px;
        font-weight: 600;
        color: var(--muted);
        margin-bottom: 64px;
      }

      .ask-stats {
        display: flex;
        flex-direction: column;
        gap: 24px;
        border-top: 1px solid rgba(0, 0, 0, 0.08);
        padding-top: 40px;
      }

      .stat-item {
        display: flex;
        align-items: baseline;
        gap: 16px;
      }

      .stat-value {
        font-size: 32px;
        font-weight: 700;
        color: var(--ink);
        width: 88px;
      }

      .stat-text {
        font-size: 22px;
        font-weight: 500;
        color: var(--muted);
      }

      /* Right Milestones Block */
      .milestones-block {
        flex: 1;
        display: flex;
        flex-direction: column;
        gap: 24px;
      }

      .milestone-card {
        background: var(--card-bg);
        border-radius: 24px;
        padding: 32px 40px;
        box-shadow: 0 4px 24px rgba(0, 0, 0, 0.03), 0 1px 4px rgba(0, 0, 0, 0.02);
        display: flex;
        align-items: center;
        gap: 32px;
        flex: 1;
      }

      .milestone-number {
        font-size: 20px;
        font-weight: 700;
        color: var(--accent);
        background: var(--accent-light);
        width: 56px;
        height: 56px;
        border-radius: 16px;
        display: flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
      }

      .milestone-content {
        display: flex;
        flex-direction: column;
        gap: 8px;
      }

      .milestone-title {
        font-size: 24px;
        font-weight: 700;
        color: var(--ink);
      }

      .milestone-desc {
        font-size: 18px;
        line-height: 1.5;
        color: var(--muted);
      }

      /* Bottom Ribbon */
      .ribbon {
        background: var(--card-bg);
        border-radius: 24px;
        padding: 28px 48px;
        box-shadow: 0 4px 24px rgba(0, 0, 0, 0.03), 0 1px 4px rgba(0, 0, 0, 0.02);
        display: flex;
        align-items: center;
        gap: 64px;
      }

      .ribbon-label {
        font-size: 16px;
        font-weight: 700;
        color: var(--muted);
        text-transform: uppercase;
        letter-spacing: 0.1em;
        flex-shrink: 0;
      }

      .ribbon-items {
        display: flex;
        flex: 1;
        justify-content: space-between;
      }

      .ribbon-item {
        display: flex;
        align-items: baseline;
        gap: 16px;
      }

      .ribbon-pct {
        font-size: 24px;
        font-weight: 700;
      }

      .ribbon-item:nth-child(1) .ribbon-pct { color: var(--accent); }
      .ribbon-item:nth-child(2) .ribbon-pct { color: #3B82F6; }
      .ribbon-item:nth-child(3) .ribbon-pct { color: #93C5FD; }

      .ribbon-desc {
        font-size: 18px;
        font-weight: 500;
        color: var(--ink);
      }
    </style>
  </head>
  <body>
    <section class="slide" aria-label="Designer Deck Slide">
      <h1 class="header">Raising $1.25M to launch pilots, prove value, and establish repeatable deployment</h1>
      <p class="subheader">Post-money SAFE • ~18–20 months of runway</p>

      <div class="master-card">
        <div class="top-section">
          <div class="ask-block">
            <div>
              <div class="ask-amount">$1.25M</div>
              <div class="ask-instrument">Post-money SAFE</div>
            </div>
            <div class="ask-stats">
              <div class="stat-item">
                <div class="stat-value">2</div>
                <div class="stat-text">core hires</div>
              </div>
              <div class="stat-item">
                <div class="stat-value">3</div>
                <div class="stat-text">pilot sites</div>
              </div>
              <div class="stat-item">
                <div class="stat-value">18–20</div>
                <div class="stat-text">months</div>
              </div>
            </div>
          </div>

          <div class="milestones-block">
            <div class="milestone-card">
              <div class="milestone-number">01</div>
              <div class="milestone-content">
                <div class="milestone-title">Build</div>
                <div class="milestone-desc">Finalize core models, complete SOC2 Type II, and harden clinical workflow integration.</div>
              </div>
            </div>
            <div class="milestone-card">
              <div class="milestone-number">02</div>
              <div class="milestone-content">
                <div class="milestone-title">Deploy</div>
                <div class="milestone-desc">Launch across 3 pilot sites, train initial user cohorts, and establish baseline metrics.</div>
              </div>
            </div>
            <div class="milestone-card">
              <div class="milestone-number">03</div>
              <div class="milestone-content">
                <div class="milestone-title">Validate</div>
                <div class="milestone-desc">Prove clinical utility, demonstrate concrete ROI, and secure first commercial conversion.</div>
              </div>
            </div>
          </div>
        </div>

        <div class="ribbon">
          <div class="ribbon-label">Use of Funds</div>
          <div class="ribbon-items">
            <div class="ribbon-item">
              <div class="ribbon-pct">50%</div>
              <div class="ribbon-desc">Engineering & Product</div>
            </div>
            <div class="ribbon-item">
              <div class="ribbon-pct">30%</div>
              <div class="ribbon-desc">Clinical Operations & Pilots</div>
            </div>
            <div class="ribbon-item">
              <div class="ribbon-pct">20%</div>
              <div class="ribbon-desc">GTM & Legal</div>
            </div>
          </div>
        </div>
      </div>

      <div class="footer-line" aria-hidden="true"></div>
      <img
        class="footer-logo"
        src="../../../../assets/logo/designer-health-logo-black.svg"
        alt=""
        aria-hidden="true"
      />
    </section>
  </body>
</html>
```
